const cluster = require('cluster');
const express = require('express');
const { authenticateMerchant } = require('../auth');

const router = express.Router();

router.post('/api/store/search-index/rebuild', authenticateMerchant, (req, res) => {
  const { storeId } = req.body;

  if (req.merchant.storeId !== storeId) {
    return res.status(403).json({ error: 'Forbidden: you cannot manage index operations for another store' });
  }

  process.send({
    type: 'TRIGGER_STORE_INDEX_REBUILD',
    storeId: storeId
  });

  res.json({ status: 'rebuild_dispatched', storeId });
});
